import config from "../../app.config";

/**
 * These assert the Info.plist entries that put dosya.dev in iOS's share sheet
 * and in Files' "Share" for documents. Same rationale as intentFilters.test.ts:
 * `ios/` is gitignored and regenerated by prebuild, the app builds and runs
 * perfectly without them, and the only symptom is "Copy to dosya.dev" silently
 * missing from every share sheet on every iPhone. Users reported exactly that
 * for PDFs and spreadsheets on 2026-09-04.
 */
describe("ios document types", () => {
  const plist = (config.ios?.infoPlist ?? {}) as Record<string, unknown>;
  const types = (plist.CFBundleDocumentTypes ?? []) as Array<Record<string, unknown>>;
  const claimed = types.flatMap((t) => (t.LSItemContentTypes as string[] | undefined) ?? []);

  it("claims generic data and content so any file type is offered", () => {
    // public.data is what a PDF, a .xlsx and a .zip all conform to. Listing
    // specific types instead (com.adobe.pdf, ...) would need a new build every
    // time a user tried a format nobody had thought of.
    expect(claimed).toContain("public.data");
    expect(claimed).toContain("public.content");
  });

  it("does not claim folders or packages", () => {
    // public.item / public.folder would list the app for directories, which
    // the receiver cannot upload. Sharing a folder would then land on the
    // picker and fail at copy time with nothing to explain why.
    expect(claimed).not.toContain("public.item");
    expect(claimed).not.toContain("public.folder");
  });

  it("ranks itself as an alternate handler, never the owner", () => {
    // "Owner" or "Default" would make dosya.dev the app iOS opens PDFs with
    // when tapped, displacing Preview/Books. That is not what a save-to app is.
    for (const t of types) expect(t.LSHandlerRank).toBe("Alternate");
  });

  it("does not open documents in place", () => {
    // In-place opening hands over a security-scoped URL that stays valid only
    // while startAccessingSecurityScopedResource is held; the upload queue
    // persists across restarts and would retry a dead handle forever - the same
    // hazard Android's content:// grant has, which is why copy.ts exists.
    // False makes iOS copy the file into Documents/Inbox, which the app owns
    // and cleans up.
    expect(plist.LSSupportsOpeningDocumentsInPlace).toBe(false);
  });

  it("declares document opening explicitly, as App Store Connect requires", () => {
    // Declaring CFBundleDocumentTypes without LSSupportsOpeningDocumentsInPlace
    // (or UISupportsDocumentBrowser) earns ITMS-90737 on every upload. Unset
    // behaves like false at runtime, so only the store notices it is missing.
    expect(Object.prototype.hasOwnProperty.call(plist, "LSSupportsOpeningDocumentsInPlace")).toBe(true);
  });
});
